  function sortDesc() {
    setScores(scores.sort((a, b) => b - a));
  }

  return (
    <div>
      <button onClick={sortDesc}>Sort high to low</button>
      <ul>
        {scores.map((s) => (
          <li key={s}>{s}</li>
        ))}
      </ul>
    </div>
  );
}

